import json

def solve(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    output = [[0]*w for _ in range(h)]

    # Find the 5-border
    r_min, r_max = h-1, 0
    c_min, c_max = w-1, 0
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 5:
                r_min = min(r_min, r)
                r_max = max(r_max, r)
                c_min = min(c_min, c)
                c_max = max(c_max, c)

    # Fill area bounds (inside 5-border)
    fill_r1 = r_min + 1
    fill_r2 = r_max - 1
    fill_c1 = c_min + 1
    fill_c2 = c_max - 1

    # Copy 5-border to output
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 5:
                output[r][c] = 5

    # Fill shells based on distance from 5-BORDER
    for r in range(fill_r1, fill_r2 + 1):
        for c in range(fill_c1, fill_c2 + 1):
            d_r = min(r - r_min, r_max - r)
            d_c = min(c - c_min, c_max - c)
            shell = min(d_r, d_c)

            if shell == 0:
                pass  # Already 5
            elif shell == 1:
                output[r][c] = 2
            elif shell == 2:
                output[r][c] = 5
            else:
                output[r][c] = 0

    return output

